CREATE TABLE `audit_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint(20) DEFAULT NULL COMMENT '操作人ID（冗余，无外键）',
  `user_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作人姓名（冗余，方便直接查看）',
  `role` tinyint(4) DEFAULT NULL COMMENT '操作人角色：0=管理员 / 1=医生 / 2=病人',
  `action` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '操作类型，如 LOGIN_SUCCESS / CREATE_DIAGNOSIS',
  `target_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作对象类型，如 appointment / diagnosis_record',
  `target_id` bigint(20) DEFAULT NULL COMMENT '操作对象ID',
  `old_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '修改前的值（JSON），如 {"stock":100}；新增操作填 NULL',
  `new_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '修改后的值（JSON），如 {"stock":80}；删除操作填 NULL',
  `detail` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作详情，如 "病人张三挂了内科王医生的号"',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '操作IP',
  `created_at` datetime NOT NULL COMMENT '操作时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_action` (`action`),
  KEY `idx_target` (`target_type`,`target_id`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=397 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='操作日志表';

