CREATE TABLE `data_dict` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dict_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '字典类型，如 user_role / appointment_status',
  `dict_key` tinyint(4) NOT NULL COMMENT '枚举值，如 0 / 1 / 2',
  `dict_label` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显示文本，如 "管理员" / "已取消"',
  `sort_order` int(11) NOT NULL DEFAULT '0' COMMENT '排序（同类型内数字小的排前面）',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_type_key` (`dict_type`,`dict_key`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='数据字典表';

