CREATE TABLE `department` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名称',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '描述',
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间（NULL=正常）',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=48 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='科室表';

INSERT INTO `department` (`id`, `name`, `description`, `deleted_at`, `created_at`, `updated_at`) VALUES (1, '心血管内科', '冠心病、高血压、心律失常、心力衰竭等心血管疾病的诊治', NULL, '2026-07-09 23:25:11', '2026-07-10 09:45:07'), (2, '呼吸内科', '肺炎、哮喘、慢阻肺、肺癌等呼吸系统疾病的诊治', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (3, '消化内科', '胃炎、胃溃疡、肝炎、胰腺炎、肠炎等消化系统疾病的诊治', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (4, '神经内科', '脑梗死、脑出血、帕金森病、癫痫、头痛眩晕等神经系统疾病的诊治', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (5, '肾内科', '肾炎、肾病综合征、肾功能衰竭等肾脏疾病的诊治及血液透析', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (6, '内分泌科', '糖尿病、甲亢、甲减、痛风、骨质疏松等内分泌代谢疾病的诊治', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (7, '血液科', '贫血、白血病、淋巴瘤、骨髓瘤等血液系统疾病的诊治', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (8, '风湿免疫科', '类风湿关节炎、系统性红斑狼疮、强直性脊柱炎等风湿免疫疾病的诊治', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (9, '肿瘤内科', '肺癌、胃癌、肝癌、乳腺癌等实体瘤的化疗、靶向治疗及免疫治疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (10, '老年病科', '老年多系统疾病的综合诊治、老年综合征评估与管理', NULL, '2026-07-09 23:25:11', '2026-07-10 11:17:04'), (11, '普外科', '甲状腺、乳腺、胃肠、肝胆胰等疾病的常规及微创手术治疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (12, '骨科', '骨折、关节置换、脊柱疾病、运动损伤等骨骼肌肉系统疾病的手术及康复', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (13, '泌尿外科', '肾结石、前列腺疾病、膀胱肿瘤等泌尿系统疾病的手术及微创治疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (14, '神经外科', '颅脑外伤、脑肿瘤、脑血管疾病、脊髓疾病的手术治疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (15, '胸外科', '肺癌、食管癌、纵隔肿瘤等胸部疾病的手术治疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (16, '心血管外科', '冠心病搭桥、心脏瓣膜置换、先天性心脏病等心血管手术', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (17, '烧伤整形外科', '烧伤救治、瘢痕修复、体表肿瘤切除及整形美容手术', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (18, '妇产科', '妇科炎症、肿瘤、内分泌疾病的诊治，产前检查、分娩及产后康复', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (19, '儿科', '儿童常见病、多发病的诊治，新生儿疾病筛查及儿童保健', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (20, '新生儿科', '早产儿、低体重儿及新生儿疾病的监护与治疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (21, '眼科', '白内障、青光眼、眼底病、屈光不正等眼部疾病的诊治及手术', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (22, '耳鼻喉科', '中耳炎、鼻炎、咽喉炎、打鼾、听力障碍等疾病的诊治及手术', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (23, '口腔科', '牙体牙髓、牙周病、口腔修复、口腔正畸及口腔颌面外科', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (24, '皮肤科', '湿疹、银屑病、荨麻疹、痤疮等皮肤病及性传播疾病的诊治', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (25, '感染科', '肝炎、结核、艾滋病、发热待查等感染性疾病的诊治', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (26, '中医科', '中药调理、针灸推拿、拔罐等中医传统诊疗方法', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (27, '康复医学科', '脑卒中后遗症、骨折术后、运动损伤等疾病的康复评定与治疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (28, '急诊科', '各类急危重症的抢救与初步处置，24小时接诊', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (29, '麻醉科', '临床麻醉、疼痛治疗、无痛诊疗及危重症抢救', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (30, '重症医学科(ICU)', '多器官功能衰竭、重症感染、严重创伤等危重症的监护与治疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (31, '精神科(心理卫生)', '抑郁症、焦虑症、失眠症、精神分裂症等精神心理疾病的诊治', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (32, '疼痛科', '颈肩腰腿痛、带状疱疹后神经痛、癌性疼痛等慢性疼痛的综合治疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (33, '全科医学科', '常见病、多发病的综合性诊疗，慢性病管理与健康管理', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (34, '介入科', '肿瘤介入、血管介入、非血管介入等微创介入诊疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (35, '检验科', '血常规、生化、免疫、微生物、分子生物学等检验项目', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (36, '放射科', 'X线、CT、MRI等影像学检查与诊断', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (37, '超声科', '腹部、心脏、血管、妇产科、小器官等超声检查与诊断', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (38, '核医学科', 'ECT、PET-CT等核医学影像检查与放射性核素治疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (39, '病理科', '组织和细胞学病理诊断、术中冰冻、免疫组化及分子病理', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (40, '内镜中心', '胃镜、肠镜、支气管镜、膀胱镜等内镜检查与治疗', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (41, '药剂科', '药品采购、调剂、临床药学、合理用药监测与咨询', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (42, '输血科', '血型鉴定、交叉配血、血液成分制备与输血管理', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (43, '营养科', '临床营养评估、治疗膳食配制、肠内肠外营养支持', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (44, '心电诊断科', '心电图、动态心电图、动态血压等心电生理检查与诊断', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (45, '体检中心', '个人及团体健康体检、入职体检、驾驶员体检及健康管理', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (46, '预防保健科', '预防接种、传染病防控、健康教育及慢病筛查', NULL, '2026-07-09 23:25:11', '2026-07-09 23:25:11'), (47, '消毒供应中心', '医疗器械清洗消毒、灭菌及无菌物品供应', NULL, '2026-07-09 23:25:11', '2026-07-11 19:37:34');

CREATE TABLE `diagnosis_record` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `appointment_id` bigint(20) NOT NULL COMMENT '挂号ID（一对一）',
  `doctor_id` bigint(20) NOT NULL COMMENT '医生ID（冗余，方便按医生查诊断历史）',
  `patient_id` bigint(20) NOT NULL COMMENT '病人ID（冗余，方便按病人查诊断历史）',
  `chief_complaint` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主诉，如"头痛3天"',
  `diagnosis_result` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '诊断结果',
  `prescription_advice` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '医嘱',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_appointment_id` (`appointment_id`),
  KEY `idx_doctor_id` (`doctor_id`),
  KEY `idx_patient_id` (`patient_id`),
  CONSTRAINT `fk_diagnosis_appointment` FOREIGN KEY (`appointment_id`) REFERENCES `appointment` (`id`),
  CONSTRAINT `fk_diagnosis_doctor` FOREIGN KEY (`doctor_id`) REFERENCES `doctor` (`id`),
  CONSTRAINT `fk_diagnosis_patient` FOREIGN KEY (`patient_id`) REFERENCES `patient` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='诊断记录表';

INSERT INTO `diagnosis_record` (`id`, `appointment_id`, `doctor_id`, `patient_id`, `chief_complaint`, `diagnosis_result`, `prescription_advice`, `created_at`, `updated_at`) VALUES (1, 124, 1, 1, '腰部疼痛', '急性胃肠炎', NULL, '2026-07-11 15:33:01', '2026-07-11 15:33:01'), (2, 125, 1, 1, '没问题', '没问题', '没问题', '2026-07-11 16:16:55', '2026-07-11 16:16:55'), (3, 129, 1, 1, '1', '11', '1', '2026-07-11 17:40:54', '2026-07-11 17:40:54'), (4, 134, 1, 1, '腿疼', '腿疼', '腿疼', '2026-07-12 10:50:35', '2026-07-12 10:50:35'), (5, 136, 1, 4, '1', '1', '1', '2026-07-12 11:20:32', '2026-07-12 11:20:32');

CREATE TABLE `doctor` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID（一对一）',
  `department_id` bigint(20) NOT NULL COMMENT '科室ID（多对一）',
  `title` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '职称，如主任医师',
  `introduction` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '简介',
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间（NULL=正常）',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id` (`user_id`),
  KEY `idx_department_id` (`department_id`),
  CONSTRAINT `fk_doctor_department` FOREIGN KEY (`department_id`) REFERENCES `department` (`id`),
  CONSTRAINT `fk_doctor_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='医生表';

INSERT INTO `doctor` (`id`, `user_id`, `department_id`, `title`, `introduction`, `deleted_at`, `created_at`, `updated_at`) VALUES (1, 2, 1, '主治医师', '心血管内科常见病及冠脉介入治疗的临床与科研工作', NULL, '2026-07-09 23:37:00', '2026-07-11 15:31:07'), (2, 3, 2, '主任医师', '擅长呼吸系统感染性疾病及肺部肿瘤的综合诊治，从医30余年', NULL, '2026-07-09 23:37:01', '2026-07-09 23:37:01'), (3, 4, 3, '副主任医师', '消化内镜诊断与治疗专家，擅长早期胃癌筛查及内镜下微创治疗', NULL, '2026-07-09 23:37:01', '2026-07-09 23:37:01'), (4, 5, 4, '主任医师', '脑血管疾病及帕金森病的诊治，神经介入治疗经验丰富', NULL, '2026-07-09 23:37:01', '2026-07-09 23:37:01'), (5, 6, 12, '副主任医师', '关节外科与运动医学，擅长髋膝关节置换及关节镜微创手术', NULL, '2026-07-09 23:37:02', '2026-07-09 23:37:02'), (6, 7, 11, '主任医师', '肝胆胰外科及胃肠肿瘤的腹腔镜微创手术，年手术量超500台', NULL, '2026-07-09 23:37:02', '2026-07-09 23:37:02'), (7, 8, 18, '主任医师', '高危妊娠管理及妇科肿瘤诊治，擅长宫腹腔镜联合手术', NULL, '2026-07-09 23:37:02', '2026-07-09 23:37:02'), (8, 9, 19, '副主任医师', '儿童呼吸系统疾病及新生儿危重症救治，深耕儿科20年', NULL, '2026-07-09 23:37:03', '2026-07-09 23:37:03'), (9, 10, 13, '主任医师', '泌尿系肿瘤及结石的微创治疗，经皮肾镜及输尿管软镜技术', NULL, '2026-07-09 23:37:03', '2026-07-09 23:37:03'), (10, 11, 21, '副主任医师', '眼底病及青光眼的诊治，擅长白内障超声乳化及玻璃体切割手术', NULL, '2026-07-09 23:37:03', '2026-07-09 23:37:03'), (11, 12, 28, '副主任医师', '急危重症抢救，擅长心肺复苏、中毒及多发伤的急诊处置', NULL, '2026-07-09 23:37:04', '2026-07-09 23:37:04'), (12, 13, 24, '主治医师', '变态反应性皮肤病及自身免疫性皮肤病的诊治', NULL, '2026-07-09 23:37:04', '2026-07-09 23:37:04'), (13, 14, 26, '主任医师', '中医内科疑难杂症，擅长心脑血管疾病及脾胃病的中医药治疗', NULL, '2026-07-09 23:37:04', '2026-07-09 23:37:04'), (14, 15, 6, '副主任医师', '糖尿病及甲状腺疾病的个体化治疗，在垂体肾上腺疾病方面有丰富经验', NULL, '2026-07-09 23:37:04', '2026-07-09 23:37:04'), (15, 16, 9, '主任医师', '肿瘤靶向治疗及免疫治疗，晚期肿瘤的综合治疗策略制定', NULL, '2026-07-09 23:37:05', '2026-07-09 23:37:05');

CREATE TABLE `doctor_schedule` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `doctor_id` bigint(20) NOT NULL COMMENT '医生ID',
  `work_date` date NOT NULL COMMENT '出诊日期',
  `start_time` time NOT NULL COMMENT '开始时间，如 08:00',
  `end_time` time NOT NULL COMMENT '结束时间，如 12:00',
  `max_patients` int(11) NOT NULL DEFAULT '10' COMMENT '该时段最大挂号数',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '状态：0=停诊 / 1=可预约',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_doctor_date` (`doctor_id`,`work_date`)
