CREATE TABLE `drug_order` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `prescription_id` bigint(20) NOT NULL COMMENT '处方ID（一对一）',
  `total_amount` decimal(10,2) DEFAULT NULL COMMENT '总金额',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '状态：0=已取消 / 1=待取药 / 2=已取药',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_prescription_id` (`prescription_id`),
  CONSTRAINT `fk_order_prescription` FOREIGN KEY (`prescription_id`) REFERENCES `prescription` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='药品订单表';

