CREATE TABLE `file_attachment` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `uploader_id` bigint(20) NOT NULL COMMENT '上传人ID',
  `uploader_role` tinyint(4) NOT NULL COMMENT '上传人角色（取值同 user_role 字典）：0=管理员 / 1=医生 / 2=病人',
  `related_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联对象类型，如 diagnosis_record / prescription',
  `related_id` bigint(20) NOT NULL COMMENT '关联对象ID',
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '原始文件名',
  `file_path` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '存储路径',
  `file_size` bigint(20) DEFAULT NULL COMMENT '文件大小（字节）',
  `file_type` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'MIME 类型，如 image/png',
  `created_at` datetime NOT NULL COMMENT '上传时间',
  PRIMARY KEY (`id`),
  KEY `idx_related` (`related_type`,`related_id`),
  KEY `idx_uploader` (`uploader_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='文件附件表';

CREATE TABLE `notification` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint(20) NOT NULL COMMENT '接收人ID',
  `title` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题，如 "挂号提醒"',
  `content` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '内容，如 "张三预约了您2026-07-10 09:00的就诊"',
  `type` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通知分类：APPOINTMENT 挂号通知 / DISPENSE 诊疗取药通知 / SYSTEM 系统公告/SYSTEM_IMPORTANT系统重要公告',
  `is_read` tinyint(4) NOT NULL DEFAULT '0' COMMENT '已读状态：0=未读 / 1=已读',
  `related_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '关联对象类型（可选，点击跳转用）',
  `related_id` bigint(20) DEFAULT NULL COMMENT '关联对象ID（可选）',
  `created_at` datetime NOT NULL COMMENT '发送时间',
  PRIMARY KEY (`id`),
  KEY `idx_user_read` (`user_id`,`is_read`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=161 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通知消息表';

