CREATE TABLE `patient` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID（一对一）',
  `gender` tinyint(4) DEFAULT NULL COMMENT '性别：0=未知 / 1=男 / 2=女',
  `birth_date` date DEFAULT NULL COMMENT '出生日期',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '居住地址',
  `blood_type` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '血型',
  `allergy_history` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '过敏史',
  `deleted_at` datetime DEFAULT NULL COMMENT '软删除时间（NULL=正常）',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id` (`user_id`),
  CONSTRAINT `fk_patient_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='病人表';

