CREATE TABLE `prescription_item` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `prescription_id` bigint(20) NOT NULL COMMENT '处方ID',
  `drug_id` bigint(20) NOT NULL COMMENT '药品ID',
  `quantity` int(11) NOT NULL COMMENT '数量',
  `usage_method` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '用法，如"一日三次，一次一片"',
  `days` int(11) DEFAULT NULL COMMENT '天数',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  KEY `idx_prescription_id` (`prescription_id`),
  KEY `idx_drug_id` (`drug_id`),
  CONSTRAINT `fk_item_drug` FOREIGN KEY (`drug_id`) REFERENCES `drug` (`id`),
  CONSTRAINT `fk_item_prescription` FOREIGN KEY (`prescription_id`) REFERENCES `prescription` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='处方明细表';

