CREATE TABLE `system_config` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `config_key` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '配置键，如 default_appointment_slots',
  `config_value` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '配置值，如 "08:00,10:00,14:00,16:00"',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '说明，如 "默认挂号时段配置"',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_config_key` (`config_key`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统配置表';

INSERT INTO `system_config` (`id`, `config_key`, `config_value`, `description`, `created_at`, `updated_at`) VALUES (13, 'default_appointment_slots', '08:30,11:00,14:00,16:30,18:30,20:30', '每天可预约时段', '2026-07-09 14:40:31', '2026-07-09 14:40:31'), (14, 'max_appointments_per_day', '50', '每位医生每日最大挂号数', '2026-07-09 14:40:31', '2026-07-09 14:40:31'), (15, 'appointment_cancel_window_hours', '2', '距预约几小时内不可取消', '2026-07-09 14:40:31', '2026-07-09 14:40:31'), (16, 'prescription_edit_window_hours', '24', '处方开具后几小时内可修改', '2026-07-09 14:40:31', '2026-07-09 14:40:31'), (17, 'default_doctor_schedule', '08:00,11:30,13:30,17:00,19:00,21:30', '医生默认上班时间', '2026-07-10 14:59:06', '2026-07-12 09:51:59');

CREATE TABLE `token_blacklist` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `token_jti` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'JWT 的 jti 声明值（唯一标识一个 token）',
  `user_id` bigint(20) NOT NULL COMMENT '所属用户ID',
  `expires_at` datetime NOT NULL COMMENT 'token 原始过期时间（过期后可清理）',
  `created_at` datetime NOT NULL COMMENT '拉黑时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_token_jti` (`token_jti`),
  KEY `idx_expires_at` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='令牌黑名单表';

CREATE TABLE `user` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码（加密存储）',
  `name` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `email` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '邮箱（登录凭证）',
  `phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '手机号（选填）',
  `role` tinyint(4) NOT NULL COMMENT '角色：0=管理员 / 1=医生 / 2=病人',
  `status` tinyint(4) NOT NULL DEFAULT '1' COMMENT '状态：0=禁用 / 1=正常',
  `last_login` datetime DEFAULT NULL COMMENT '最后登录时间',
  `created_at` datetime NOT NULL COMMENT '创建时间',
  `updated_at` datetime NOT NULL COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_email` (`email`),
  UNIQUE KEY `uk_phone` (`phone`)
) ENGINE=InnoDB AUTO_INCREMENT=51 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户表';

