CREATE TABLE `verification_code` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `target` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '接收方（手机号或邮箱）',
  `code` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '验证码（6位数字）',
  `scene` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '使用场景：REGISTER / LOGIN / RESET_PASSWORD',
  `send_ip` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发送请求的IP（用于防刷风控）',
  `attempt_count` tinyint(4) NOT NULL DEFAULT '0' COMMENT '校验失败次数（连续输错3次即作废）',
  `expires_at` datetime NOT NULL COMMENT '过期时间，如发送后5分钟',
  `used` tinyint(4) NOT NULL DEFAULT '0' COMMENT '是否已使用：0=未使用 / 1=已使用',
  `created_at` datetime NOT NULL COMMENT '发送时间',
  PRIMARY KEY (`id`),
  KEY `idx_target_scene` (`target`,`scene`),
  KEY `idx_expires_at` (`expires_at`)
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='验证码表';

